using System;using System.Linq;using BeamScheduleFormatter;
class StructuralColumnTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}
 static void Main(){var cfg=new LengthConfiguration{Name="Column fixture",GradeSmall=40,GradeLarge=60,FySmall=275,FyLarge=420,Input=new LengthInput{Fc=28,Round=25,Simplified=true}};
 var c=MiscStructureTakeoff.Member("Column Estimate","C1","Ground floor",3,300,300,2,40,16,8,12,0,10,"Spacing (mm)",150,50,400,false,0,cfg);Near(c.Concrete,.54,"Column concrete includes both members");Near(c.Forms,7.2,"Four column faces, no soffit or end forms");var main=c.Steel.Result.Lines.Single(x=>x.Part=="Column longitudinal");Check(main.Grade==60&&main.Diameter==16&&main.PiecesPerBeam==8,"Approved longitudinal count and material grade");Near(main.CutLength,3.325,"Cover and total end allowance with standard purchase rounding");var ties=c.Steel.Result.Lines.Single(x=>x.Part=="Stirrups");Check(ties.TieSetsPerBeam==21&&ties.Grade==40,"Tie spacing includes both end stations and selected grade");
 var counted=MiscStructureTakeoff.Member("Column Estimate","C2","Upper floor",3,300,300,2,40,16,8,12,0,10,"Number of ties",21,50,400,false,0,cfg);Near(c.Steel.Result.Total,counted.Steel.Result.Total,"Equivalent tie spacing/count give identical rebar mass");Near(c.Steel.Result.Total,c.Steel.Result.Lines.Sum(x=>x.Kg),"Column main steel and ties counted once");var plan=CommercialBars.Allocate(new[]{c.Steel},cfg,new[]{6.0});Check(plan.Any()&&plan.All(a=>a.Choice!=null),"Column cuts included in commercial bar purchase plan");Check(BackupPayItemCatalog.Concrete("Structural",false)!=BackupPayItemCatalog.Concrete("Miscellaneous",false),"Structural column has distinct concrete group from stiffener columns");foreach(string header in new[]{"Qty","Wall Qty","Roof Qty","Quantity (pcs)","Runs","Pieces"})Check(QuantityInputDefaults.IsMultiplier(header),"Manual item count recognized: "+header);foreach(string header in new[]{"Rebar layers (1/2)","Main bars per column","Number of ties","Locksets/unit"})Check(!QuantityInputDefaults.IsMultiplier(header),"Design/detail count remains separate: "+header);foreach(string legacy in new[]{"On gravel fill","Ground beam","On Fill"})Check(BeamSupportInput.Normalize(legacy)=="On Fill","Saved support migration: "+legacy);foreach(string legacy in new[]{"Elevated slab","Elevated",""})Check(BeamSupportInput.Normalize(legacy)=="Elevated","Elevated saved support migration");Console.WriteLine("PASS: "+checks+" structural-column quantity and purchase checks");}
}
